sys_script_include.script:
function GetAppManagerPath(vPluginOrStoreApp)
{
	var grPlugin = GetPluginRecord(vPluginOrStoreApp);
	var grStoreApp = GetStoreAppRecord(vPluginOrStoreApp);
	var grRemoteApp = GetRecord('sys_remote_app',vPluginOrStoreApp);
	if (IsValidRecord(grRemoteApp) == false)
	{
		grRemoteApp = RecordQuery('sys_remote_app', { scope: GetStringValue(vPluginOrStoreApp) });
	}
	var strPluginOrStoreApp = GetStringValue(vPluginOrStoreApp);

	var strPath = 'now/app-manager/home/';

	if (IsValidRecord(grPlugin) == true)
	{
		strPath += 'plugin/id/'+grPlugin.source+'/details';
	}
	else if (IsValidRecord(grStoreApp) == true)
	{
		strPath += 'app/id/'+grStoreApp.sys_id+'/';
	}
	else if (IsValidRecord(grRemoteApp) == true)
	{
		strPath += 'app/id/'+grRemoteApp.sys_id+'/';
	}	
	else if (IsValidPluginId(strPluginOrStoreApp) == true)
	{
		strPath += 'plugin/id/'+strPluginOrStoreApp+'/details';
	}
	else if (IsValidSysId(strPluginOrStoreApp) == true)
	{
		strPath += 'app/id/'+strPluginOrStoreApp+'/';
	}
	return strPath;
}
